async function doLogin(){grab();if(!D.email||!$('pw').value)return toast('Enter email and password');try{await signIn(auth,D.email,$('pw').value)}catch(e){toast(errMsg(e))}}
async function next(skip){grab();const st=STEPS()[S.step-1];
 if(st=='acct'){if(!/^\S+@\S+\.\S+$/.test(D.email||''))return toast('Enter a valid email');if((D.pw||'').length<6)return toast('Password must be at least 6 characters')}
 if(st=='about'){if(!D.name)return toast('Please enter your name');if(!(+D.age>=16))return toast('FoundX is for people aged 16 and above. Enter your real age.')}
 if(S.step<STEPS().length){S.step++;return render()}
 try{S.busy=true;render();let email=D.email;if(S.mode=='signup'){await signUp(auth,D.email,D.pw);try{await sendEmailVerification(auth.currentUser)}catch(e){}}else email=auth.currentUser.email;if(!(STG[D.jt||'Startup']||EX).includes(D.exec))D.exec='';
  await setDoc(doc(db,'users',auth.currentUser.uid),{name:D.name,age:+D.age||0,cls:D.cls||'',country:D.country||'',city:D.city||'',field:(D.roles||[])[0]||'',roles:D.roles||[],role:(D.roles||[])[0]||'',jt:D.jt||'',look:D.look||'',needs:D.needs||[],bio:D.bio||'',idea:D.idea||'',exec:D.exec||'',created:Date.now(),lastSeen:Date.now(),avail:'Available'});await setDoc(doc(db,'users',auth.currentUser.uid,'private','info'),{email,phone:D.phone||'',dob:D.dob||''});try{const rf=localStorage.getItem('fx_ref');if(rf&&rf!==auth.currentUser.uid){await setDoc(doc(db,'referrals',auth.currentUser.uid),{by:rf,ts:Date.now()});localStorage.removeItem('fx_ref')}}catch(e){}
  S.busy=false;S.mode='login';D.pw='';toast('Welcome to FoundX! 🎉')}catch(e){S.busy=false;S.step=1;S.mode=S.mode=='onboard'?'onboard':'signup';render();toast(errMsg(e))}}

