const referV=()=>`<h2 style="font-size:1.4rem;font-weight:800">🎁 Invite &amp; Earn</h2><p style="color:var(--mu);margin:4px 0 0">Invite friends and earn points. 500 points = free tag + blue tick.</p>`+refBox();
