const rowH=(t,h)=>h?`<div style="margin-top:10px"><div style="font-size:.7rem;font-weight:700;color:var(--mu);letter-spacing:.04em">${t}</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:5px">${h}</div></div>`:'';
const tagRow=(t,arr,c)=>arr.length?`<div style="margin-top:10px"><div style="font-size:.7rem;font-weight:700;color:var(--mu);letter-spacing:.04em">${t}</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:5px">${arr.map(x=>`<span class="badge" style="--c:${c}">${esc(x)}</span>`).join('')}</div></div>`:'';
const aboutTags=u=>{const rl=u.roles&&u.roles.length?u.roles:u.role?[u.role]:[],h=tagRow('INTO',rl,'#7A5AF8')+tagRow('CITY',u.city?[u.city]:[],'#0EA5A4')+rowH('STATUS',availTag(u))+tagRow('LOOKING FOR',u.look?[u.look]:[],'#12B76A');return h?`<div style="margin-top:16px;background:var(--c2);border-radius:14px;padding:4px 14px 14px"><div style="font-size:.75rem;color:var(--mu);margin-top:12px">🏷️ ABOUT</div>${h}</div>`:''};
const growthCard=id=>{const hp=posts.filter(p=>p.uid==id&&!p.official).reduce((a,p)=>a+(p.likes||[]).length,0),n=streak(id),goal=n>=10?30:10,prev=n>=10?10:0,pct=n>=30?100:Math.min(100,(n-prev)/(goal-prev)*100),t=tagsOf(id),txt=n>=30?'⚡ 30-day tag earned!':`🔥 ${n}/${goal} days to ${goal==10?'your first streak tag':'the 30-day tag'}`;
 return `<div style="margin-top:12px;background:var(--c2);border-radius:14px;padding:14px"><div style="font-size:.75rem;color:var(--mu)">🌱 GROWTH &amp; TAGS</div><div style="display:flex;justify-content:space-between;gap:8px;font-size:.85rem;margin-top:8px;flex-wrap:wrap"><b>${txt}</b><span style="color:var(--mu)">${n} day streak</span></div><div class="bar" style="margin-top:6px"><i style="width:${pct}%"></i></div><div style="margin-top:8px;font-size:.85rem">🙌 <b>${hp}</b> helpful votes received</div>${lvBar(id)}<div style="margin-top:12px;font-size:.7rem;font-weight:700;color:var(--mu);letter-spacing:.04em">EARNED TAGS</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:5px">${t||'<span style="color:var(--mu);font-size:.85rem">No tags yet. Post daily to earn one.</span>'}</div></div>`};
// ---------- post types (idea / learned / win / question / need help) ----------
const PT={moment:'📸 Moment',hot:'🔥 Hot take',win:'🏆 Win',ask:'❓ Ask',challenge:'🎯 Challenge'},PC={moment:'#0EA5A4',hot:'#FF5A1F',win:'#12B76A',ask:'#7A5AF8',challenge:'#E83E8C'};
const flab=f=>f=='Trending'?'🔥 Trending':f.startsWith('type:')?PT[f.slice(5)]:f;
const ptChips=()=>Object.entries(PT).map(([k,l])=>`<button class="chip ${S.ptype==k?'on':''}" onclick="setPT('${k}')">${l}</button>`).join('');
const setPT=k=>{S.ptype=S.ptype==k?'':k;const el=document.querySelector('.sheet #ptc');if(el)el.innerHTML=ptChips()};
