const inApp=/Instagram|FBAN|FBAV|FB_IAB|Snapchat|musical_ly|Line\//i.test(navigator.userAgent);
const signInBody=()=>`<div class="mlogo" style="margin-bottom:10px"><span class="stk flt">🔥 Day 4 of my journey</span> <span class="stk flt" style="background:#fff;animation-delay:.8s">🏆 First win</span></div><h2 style="font-size:1.5rem;font-weight:800">Join in one tap 🚀</h2><p style="color:var(--mu);margin:4px 0 14px">No password. Takes about 20 seconds.</p>`+
 (inApp?`<div class="card" style="padding:12px;margin-bottom:12px;animation:none"><b>Open in Chrome or Safari</b><div style="font-size:.85rem;color:var(--mu);margin-top:2px">Google sign-in doesn't work inside Instagram. Tap ⋯ and choose "Open in browser", or use the email link below.</div><button class="ghost" style="margin-top:8px" onclick="copyLink()">Copy link</button></div>`:'')+
 `<button class="btn gshine" style="width:100%;display:flex;align-items:center;justify-content:center;gap:10px;font-size:1.05rem;padding:.8rem" onclick="googleIn()"><span style="background:#fff;border-radius:50%;width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center;font:800 15px Arial;color:#4285F4">G</span>Continue with Google</button><button class="ghost" style="width:100%;margin-top:10px;background:var(--y);color:#1A1612;border-color:var(--ink)" onclick="peek()">👀 Peek inside first</button>`+
 `<details style="margin-top:16px" ${inApp?'open':''}><summary style="cursor:pointer;text-align:center;font-weight:600;font-size:.88rem;color:var(--mu)">✉️ Use email link instead</summary>${inp('Email','em','email',D.email,'you@email.com')}<button class="ghost" style="width:100%;margin-top:10px" onclick="sendLink()">Send me a login link</button></details>`+
 `<p style="font-size:.75rem;color:var(--mu);margin-top:16px;text-align:center">By continuing you agree to our <a href="privacy.html" style="color:var(--a);font-weight:700">Privacy &amp; Terms</a>. FoundX is for ages 16+. Posts in the background are samples.</p>`;
async function googleIn(){const pr=new GoogleAuthProvider();pr.setCustomParameters({prompt:'select_account'});
 try{await signInWithPopup(auth,pr)}catch(e){
  if(['auth/popup-blocked','auth/operation-not-supported-in-this-environment'].includes(e.code)){try{await signInWithRedirect(auth,pr)}catch(x){toast(errMsg(x))}}
  else if(!['auth/popup-closed-by-user','auth/cancelled-popup-request'].includes(e.code))toast(e.code=='auth/operation-not-allowed'?'Google login is not switched on in Firebase yet':errMsg(e))}}
const copyLink=()=>{navigator.clipboard?.writeText(location.href);toast('Link copied. Paste it in Chrome or Safari')};
Object.assign(window,{googleIn,copyLink});
// ---------- levels (XP), confetti, pops ----------
const LV=[['Rookie',0,'#6E6256','🌱'],['Regular',50,'#2D6CFF','🔥'],['Rising',200,'#E58A00','⚡'],['Legend',500,'#FF5A1F','👑']];
const lvOf=id=>{const m=posts.filter(p=>p.uid==id&&!p.official),x=m.length*10+m.reduce((a,p)=>a+(p.likes||[]).length,0)*2+streak(id)*5;let i=0;LV.forEach((l,k)=>{if(x>=l[1])i=k});const l=LV[i],nx=LV[i+1];return{x,l,nx,pct:nx?Math.min(100,(x-l[1])/(nx[1]-l[1])*100):100}};
const lvChip=id=>{const{l}=lvOf(id);return `<span class="badge" style="--c:${l[2]}">${l[3]} ${l[0]}</span>`};
const lvBar=id=>{const{x,l,nx,pct}=lvOf(id);return `<div style="margin-top:12px;font-size:.7rem;font-weight:700;color:var(--mu);letter-spacing:.04em">LEVEL</div><div style="display:flex;justify-content:space-between;gap:8px;font-size:.85rem;margin-top:4px;flex-wrap:wrap"><b>${l[3]} ${l[0]}</b><span style="color:var(--mu)">${x} XP${nx?' · '+(nx[1]-x)+' to '+nx[0]:''}</span></div><div class="bar" style="margin-top:5px"><i style="width:${pct}%"></i></div><div style="font-size:.72rem;color:var(--mu);margin-top:4px">10 XP per post · 5 per streak day · 2 per helpful vote</div>`};
document.head.insertAdjacentHTML('beforeend','<style>.flt{animation:flt 3.2s ease-in-out infinite alternate}@keyframes flt{to{transform:translateY(-7px) rotate(2deg)}}.flame{display:inline-block;animation:flm 1.1s ease-in-out infinite alternate}@keyframes flm{to{transform:scale(1.2) rotate(-7deg)}}.cfw{position:fixed;inset:0;pointer-events:none;z-index:99;overflow:hidden}.cfw i{position:absolute;top:-30px;font-style:normal;font-size:1.4rem;animation:cfall 1.8s ease-in forwards;animation-delay:var(--d)}@keyframes cfall{to{transform:translateY(105vh) rotate(var(--r));opacity:.9}}.pop{position:fixed;font-size:1.8rem;pointer-events:none;z-index:99;transform:translate(-50%,-50%);animation:pup .9s ease-out forwards}@keyframes pup{to{transform:translate(-50%,-130px) scale(1.6);opacity:0}}</style>');
function confetti(){const e=['🎉','✨','🔥','🙌','🚀'],w=document.createElement('div');w.className='cfw';w.innerHTML=Array.from({length:18},(_,i)=>`<i style="left:${Math.random()*100}%;--d:${(Math.random()*.5).toFixed(2)}s;--r:${Math.round(Math.random()*360)}deg">${e[i%5]}</i>`).join('');document.body.appendChild(w);setTimeout(()=>w.remove(),2400)}
let LP=[innerWidth/2,innerHeight/2];addEventListener('pointerdown',e=>{LP=[e.clientX,e.clientY]},true);
function pop(em){const d=document.createElement('div');d.className='pop';d.textContent=em;d.style.left=LP[0]+'px';d.style.top=LP[1]+'px';document.body.appendChild(d);setTimeout(()=>d.remove(),900)}
// ---------- animated landing: sample feed wall + "peek inside" demo (code only, ~0 MB) ----------
const WN=['Riya','Aman','Sneha','Karan','Meera','Dev'];
const WP=[['win','Our squad just hit a 14-day streak. Nobody broke the chain.'],['moment','Sunset from my terrace. No filter, I swear.'],['hot','Pineapple on pizza is fine. Fight me.'],['ask','Best song for a long bus ride? Drop one.'],['challenge','Week challenge: my desk setup. Rate it.'],['win','Beat the other squad by 20 points. Dinner is on them.']];
const wc=i=>{const[t,x]=WP[i%6],n=WN[i%6];return `<div class="wp"><div class="wh"><span class="av" style="width:24px;height:24px;font-size:11px;background:${PAL[i%6]}">${n[0]}</span><b>${n}</b><span class="badge" style="--c:${PC[t]}">${PT[t]}</span></div><p>${x}</p><div class="wf">${icn('heart',14)} Helpful</div></div>`};
const wallHTML=()=>{const col=(o,k)=>`<div class="wcol ${k}">${[0,1].map(()=>Array.from({length:6},(_,i)=>wc(i+o)).join('')).join('')}</div>`;return `<div class="wall" aria-hidden="true"><div class="wcols">${col(0,'wa')}${col(2,'wb')}${col(4,'wa w3')}</div></div>`};
const peekJoin=()=>toast('Join to like, comment and chat 🙂');
function peek(){ov(`<div class="card" style="background:var(--bg);padding:16px;width:min(460px,100%);max-height:88vh;overflow:auto;animation:none"><div style="display:flex;align-items:center;gap:8px"><b style="flex:1;font-size:1.1rem">👀 Sneak peek</b><span class="badge" style="--c:#6E6256">Sample posts</span><button class="ghost" aria-label="Close" onclick="closeOv()">✕</button></div>${WP.map(([t,x],i)=>`<div class="card" style="padding:14px;margin-top:12px;animation:none"><div style="display:flex;gap:10px;align-items:center"><span class="av" style="width:36px;height:36px;font-size:15px;background:${PAL[i%6]}">${WN[i][0]}</span><div style="flex:1"><b>${WN[i]}</b> <span class="badge" style="--c:${PC[t]}">${PT[t]}</span><div style="font-size:.75rem;color:var(--mu)">Day ${i*3+4} · ${i+1}h</div></div></div><p style="margin-top:10px">${x}</p><div style="display:flex;gap:6px;margin-top:10px"><button class="ghost" onclick="peekJoin()">${icn('heart',18)} Helpful · ${12-i*2}</button><button class="ghost" onclick="peekJoin()">${icn('chat',18)} ${i+2}</button></div></div>`).join('')}<div style="position:sticky;bottom:-16px;background:var(--bg);padding:12px 0 0;margin-top:8px"><button class="btn gshine" style="width:100%" onclick="closeOv();googleIn()">Continue with Google</button></div></div>`)}
Object.assign(window,{peek,peekJoin});
document.head.insertAdjacentHTML('beforeend','<style>.wall{position:fixed;inset:0;overflow:hidden;pointer-events:none;z-index:0;opacity:.32}.wcols{position:absolute;left:-6%;right:-6%;top:-12%;bottom:-12%;display:flex;gap:14px;transform:rotate(-6deg)}.wcol{flex:1;display:flex;flex-direction:column;gap:14px;will-change:transform}.wcol.wa{animation:wup 40s linear infinite}.wcol.wb{animation:wdn 46s linear infinite}@keyframes wup{to{transform:translateY(-50%)}}@keyframes wdn{from{transform:translateY(-50%)}to{transform:translateY(0)}}.wp{background:var(--card);border:2px solid var(--cb);border-radius:14px;padding:10px;box-shadow:3px 3px 0 var(--cb);font-size:.8rem}.wh{display:flex;gap:7px;align-items:center}.wp p{margin-top:6px}.wf{margin-top:6px;color:var(--mu)}.auth>.hero,.auth>.card{position:relative;z-index:1}@media(max-width:760px){.w3{display:none}}.rot{display:block;height:1.15em;overflow:hidden}.rin{display:block;animation:rot 10s ease-in-out infinite}.rl{display:block;height:1.15em;line-height:1.15;white-space:nowrap}@keyframes rot{0%,22%{transform:translateY(0)}25%,47%{transform:translateY(-1.15em)}50%,72%{transform:translateY(-2.3em)}75%,100%{transform:translateY(-3.45em)}}.gshine{position:relative;overflow:hidden}.gshine::after{content:"";position:absolute;top:0;left:-60%;width:35%;height:100%;background:rgba(255,255,255,.4);transform:skewX(-20deg);animation:shn2 3.4s ease-in-out infinite}@keyframes shn2{to{left:130%}}</style>');
// ---------- Squads + weekly season ----------
const THEMES=['Your desk or study setup','Your most-played song this week','Fit of the week','Something you made with your hands','A place that feels like home','Your funniest screenshot (no faces)','Best view from your window','What you ate today','A pet or a street cat you met','Your favourite corner of your city'];
const wkStart=(t=Date.now())=>{const d=new Date(t);d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.getTime()};
const wkNum=()=>Math.floor(wkStart()/(7*DAY)),weekTheme=()=>THEMES[wkNum()%THEMES.length];
const wkY=()=>{const w=new Date(wkStart());return Math.ceil(((w-new Date(w.getFullYear(),0,1))/DAY+1)/7)};
const leftTxt=()=>{const ms=Math.max(0,wkStart()+7*DAY-Date.now()),d=ms/DAY|0,h=(ms%DAY)/36e5|0;return d?d+'d '+h+'h':h+'h '+((ms%36e5)/6e4|0)+'m'};
const memberPts=(uid,from=wkStart(),to=Infinity)=>{const per={};let pts=0;posts.filter(p=>p.uid==uid&&!p.official&&p.ts>=from&&p.ts<to).forEach(p=>{const k=new Date(p.ts).toDateString();per[k]=(per[k]||0)+1;if(per[k]<=5)pts+=(p.type=='challenge'?20:10)+Math.min(10,(p.likes||[]).length)*2});return pts};
const sqPts=(s,from,to)=>(s.members||[]).reduce((a,u)=>a+memberPts(u,from,to),0);
const sqStreak=s=>{const m=new Set(s.members||[]),d=new Set(posts.filter(p=>m.has(p.uid)&&!p.official).map(p=>new Date(p.ts).toDateString()));let n=0,t=new Date();if(!d.has(t.toDateString()))t.setDate(t.getDate()-1);while(d.has(t.toDateString())){n++;t.setDate(t.getDate()-1)}return n};
const board=(from,to)=>squads.map(s=>({s,p:sqPts(s,from,to)})).filter(x=>x.p>0).sort((a,b)=>b.p-a.p);
const mySq=()=>squads.filter(s=>(s.members||[]).includes(S.uid));
const seasonBanner=()=>`<div class="card" style="padding:12px 14px;margin-bottom:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;cursor:pointer" onclick="go('squad')"><div style="flex:1;min-width:180px"><div style="font-size:.7rem;font-weight:700;color:var(--mu);letter-spacing:.04em">🏆 WEEK ${wkY()} CHALLENGE · ENDS IN ${leftTxt().toUpperCase()}</div><b>${esc(weekTheme())}</b></div><span class="btn" style="padding:.35rem .9rem">Play</span></div>`;
const sqCard=(s,rk)=>`<div class="card" style="padding:14px;margin-top:10px;cursor:pointer" onclick="S.sq='${s.id}';renderView()"><div style="display:flex;align-items:center;gap:10px"><b style="flex:1;min-width:0;font-size:1.05rem">${esc(s.name)}</b><span class="badge" style="--c:#FF5A1F">${rk}</span></div><div style="display:flex;align-items:center;margin-top:8px">${(s.members||[]).slice(0,6).map(u=>`<span style="margin-right:-8px">${av(U(u).name,30)}</span>`).join('')}<span style="margin-left:16px;font-size:.8rem;color:var(--mu)">${(s.members||[]).length} members</span></div><div style="display:flex;gap:14px;margin-top:10px;font-size:.85rem;flex-wrap:wrap"><span><b>${sqPts(s)}</b> pts</span><span><span class="flame">🔥</span> <b>${sqStreak(s)}</b> day squad streak</span></div></div>`;
function squadDetail(s){const own=s.admin==S.uid,ms=(s.members||[]).map(u=>({u,p:memberPts(u)})).sort((a,b)=>b.p-a.p),mx=Math.max(1,...ms.map(x=>x.p));
 return `<button class="ghost" onclick="S.sq=null;renderView()">← Squads</button><div class="card" style="padding:16px;margin-top:12px"><h2 style="font-weight:800">${esc(s.name)}</h2><div style="display:flex;gap:16px;margin-top:8px;flex-wrap:wrap"><span><b>${sqPts(s)}</b> pts this week</span><span><span class="flame">🔥</span> <b>${sqStreak(s)}</b> day streak</span></div><p style="font-size:.8rem;color:var(--mu);margin-top:6px">The squad streak counts every day at least one member posts.</p><button class="btn" style="margin-top:10px" onclick="S.ptype='challenge';composePost()">Post for the squad</button></div>
<div class="card" style="padding:14px;margin-top:12px"><b>Members · ${ms.length}/8</b>${ms.map(x=>`<div style="margin-top:10px"><div style="display:flex;align-items:center;gap:10px"><div style="cursor:pointer" onclick="go('profile',{peer:'${x.u}'})">${av(U(x.u).name,32,x.u)}</div><b style="flex:1;min-width:0">${esc(U(x.u).name)}${x.u==s.admin?' <span class="badge" style="--c:#7A5AF8">admin</span>':''}</b><span style="font-size:.85rem">${x.p} pts</span>${own&&x.u!=S.uid?`<button class="ghost" style="padding:.2rem .6rem" aria-label="Remove" onclick="removeMember('${s.id}','${x.u}')">✕</button>`:''}</div><div class="bar" style="margin-top:5px"><i style="width:${x.p/mx*100}%"></i></div></div>`).join('')}${own&&ms.length<8?`<button class="ghost" style="width:100%;margin-top:12px" onclick="addToSquad('${s.id}')">＋ Add friends</button>`:''}</div>
<button class="ghost" style="width:100%;margin-top:12px;color:#ef4444" onclick="${own?`delSquad('${s.id}')`:`leaveSquad('${s.id}')`}">${own?'Delete squad':'Leave squad'}</button>`}
function squadV(){if(S.sq){const s=squads.find(x=>x.id==S.sq);if(s)return squadDetail(s);S.sq=null}
 const mine=mySq(),bd=board(wkStart()),lw=board(wkStart()-7*DAY,wkStart())[0],rank=s=>{const i=bd.findIndex(x=>x.s.id==s.id);return i<0?'—':'#'+(i+1)};
 return `<h2 style="font-size:1.4rem;font-weight:800">👥 Squads</h2><p style="color:var(--mu);margin:4px 0 0">Play the weekly challenge with your friends. Fresh start every Monday.</p>
<div class="card" style="padding:16px;margin-top:12px"><div style="font-size:.7rem;font-weight:700;color:var(--mu);letter-spacing:.04em">🎯 THIS WEEK · ENDS IN ${leftTxt().toUpperCase()}</div><h3 style="margin-top:6px;font-weight:800">${esc(weekTheme())}</h3><p style="color:var(--mu);font-size:.85rem;margin-top:4px">Post your entry. Challenge posts give 20 points, other posts 10. Never share your phone number, address or school.</p><button class="btn" style="margin-top:10px" onclick="S.ptype='challenge';composePost()">Post my entry</button></div>
<div class="card" style="padding:14px;margin-top:12px;display:flex;gap:12px;align-items:center;cursor:pointer" onclick="go('quiz')"><span style="font-size:1.8rem">🎮</span><div style="flex:1;min-width:0"><b>How well do you know me?</b><div style="font-size:.82rem;color:var(--mu)">A quiz for 2 or 3 friends. Get your friendship score.${quizzes.filter(q=>q.host!=S.uid&&!(q.guesses||{})[S.uid]).length?' <b style="color:var(--a)">'+quizzes.filter(q=>q.host!=S.uid&&!(q.guesses||{})[S.uid]).length+' waiting for you</b>':''}</div></div><span class="btn" style="padding:.35rem .9rem">Play</span></div>
${lw?`<div class="card" style="padding:12px 14px;margin-top:12px">🏆 Last week's winner: <b>${esc(lw.s.name)}</b> · ${lw.p} pts</div>`:''}
<div style="display:flex;align-items:center;margin-top:16px"><b style="flex:1">Your squads</b><button class="btn" onclick="newSquad()">＋ New squad</button></div>
${mine.map(s=>sqCard(s,rank(s))).join('')||`<div class="card" style="padding:28px;text-align:center;margin-top:10px;color:var(--mu)"><div style="font-size:2rem">👥</div>No squad yet.<br>Make one with your friends.</div>`}
<b style="display:block;margin-top:18px">Leaderboard · this week</b>
${bd.slice(0,10).map((x,i)=>`<div class="card" style="padding:10px 14px;margin-top:8px;display:flex;gap:10px;align-items:center;${(x.s.members||[]).includes(S.uid)?'border-color:var(--a)':''}"><b style="width:28px">${i+1}</b><span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(x.s.name)}</span><b>${x.p} pts</b></div>`).join('')||'<p style="color:var(--mu);margin-top:8px">No points yet this week. Be the first!</p>'}`}
function newSquad(){S.gsel=new Set();const f=friendIds(S.uid);ov(box(`<h3 style="font-weight:800">New squad</h3><input id="sqn" class="inp" maxlength="30" placeholder="Squad name" style="margin-top:10px"><label class="l">Add friends (up to 7)</label>${f.length?pickList(f):'<p style="color:var(--mu)">You have no friends here yet. Add friends from Explore, then make a squad.</p>'}<div style="display:flex;gap:10px;margin-top:14px"><button class="ghost" onclick="closeOv()">Cancel</button><button class="btn" style="flex:1" onclick="makeSquad()">Create squad</button></div>`))}
async function makeSquad(){const n=($('sqn').value||'').trim();if(n.length<2)return toast('Give your squad a name');const m=[S.uid,...[...S.gsel].slice(0,7)];
 try{const r=await addDoc(collection(db,'squads'),{name:n,members:m,admin:S.uid,created:Date.now()});m.slice(1).forEach(u=>notify(u,'squad',r.id));closeOv();Object.assign(S,{view:'squad',sq:r.id});render();confetti();toast('Squad created 🎉')}catch(e){toast(errMsg(e))}}
function addToSquad(id){const s=squads.find(x=>x.id==id);if(!s)return;S.gsel=new Set();const f=friendIds(S.uid).filter(u=>!(s.members||[]).includes(u));
 ov(box(`<h3 style="font-weight:800">Add friends</h3>${f.length?pickList(f):'<p style="color:var(--mu);margin-top:8px">All your friends are already here, or you have no friends yet.</p>'}<div style="display:flex;gap:10px;margin-top:14px"><button class="ghost" onclick="closeOv()">Cancel</button><button class="btn" style="flex:1" onclick="doAddSquad('${id}')">Add</button></div>`))}
async function doAddSquad(id){const s=squads.find(x=>x.id==id);if(!s||!S.gsel.size)return toast('Pick friends first');const a=[...S.gsel].slice(0,8-(s.members||[]).length);
 try{await updateDoc(doc(db,'squads',id),{members:arrayUnion(...a)});a.forEach(u=>notify(u,'squad',id));closeOv();toast('Added ✅')}catch(e){toast(errMsg(e))}}
const removeMember=(id,u)=>confirm('Remove this member?')&&updateDoc(doc(db,'squads',id),{members:arrayRemove(u)}).then(()=>toast('Removed')).catch(e=>toast(errMsg(e)));
const leaveSquad=id=>confirm('Leave this squad?')&&updateDoc(doc(db,'squads',id),{members:arrayRemove(S.uid)}).then(()=>{S.sq=null;renderView();toast('You left the squad')}).catch(e=>toast(errMsg(e)));
const delSquad=id=>confirm('Delete this squad for everyone?')&&deleteDoc(doc(db,'squads',id)).then(()=>{S.sq=null;renderView();toast('Squad deleted')}).catch(e=>toast(errMsg(e)));
Object.assign(window,{newSquad,makeSquad,addToSquad,doAddSquad,removeMember,leaveSquad,delSquad});
// ---------- game: "How well do you know me?" (2 or 3 friends, async) ----------
const QB=[['Favourite food?',['Pizza','Biryani','Momos','Burger']],['Perfect weekend?',['Sleeping all day','Out with friends','Gaming or movies','Travelling']],['How do they chat?',['Long texts','Voice notes','Memes only','Calls']],['Favourite season?',['Summer','Monsoon','Winter','Spring']],['Phone battery is usually…',['Above 50%','Around 20%','Dead by evening','Powerbank hero']],['Morning or night?',['Early bird','Night owl','Anytime napper','Depends on exams']],['Biggest fear?',['Exams','Lizards','Public speaking','Heights']],['Favourite music?',['Bollywood','Hip-hop','Lo-fi','Punjabi or Rock']],['Dream trip?',['Goa','Manali','Dubai','Japan']],['Food choice?',['Home food','Street food','Cafe food','Anything free']],['Reply speed?',['Instant','After an hour','Next day','Seen only']],['Superpower?',['Invisible','Fly','Read minds','Time travel']],['Alone time?',['Need a lot','A little','Never','Depends on mood']],['Study style?',['Night before exam','Early and steady','Group study','Last 10 minutes']],['Social media?',['Reels addict','Only stories','Barely use','Silent lurker']],['Ideal hangout?',['Cafe','Movie','Long drive','Home chill']]];
const QE=[['🍕','🍛','🥟','🍔'],['😴','🎉','🎮','🧳'],['📝','🎙️','😂','📞'],['☀️','🌧️','❄️','🌸'],['🔋','🪫','💀','⚡'],['🌅','🦉','🛌','📚'],['📖','🦎','🎤','🏔️'],['🎬','🎧','🌙','🎸'],['🏖️','⛰️','🏙️','🗼'],['🏠','🍢','☕','🆓'],['⚡','⏳','📅','👀'],['🫥','🕊️','🧠','⏰'],['🧘','🙂','🙅','🌗'],['🌙','⏰','👯','😅'],['📱','📸','🙈','🕵️'],['☕','🍿','🚗','🛋️']];
const QCOL=['#FF5A1F','#2D6CFF','#12B76A','#E58A00'];
const TIER=['Strangers with Wi-Fi','Strangers with Wi-Fi','Still getting to know each other','Solid friend','Certified bestie','Soulmate level'],TEM=['🫥','🫥','🙂','🤝','🔥','👑'];
const buzz=()=>{try{navigator.vibrate&&navigator.vibrate(25)}catch(e){}};
const qScore=(q,g)=>(g||[]).filter((a,i)=>a===q.qs[i].ans).length;
document.head.insertAdjacentHTML('beforeend','<style>.qo{display:flex;align-items:center;gap:12px;width:100%;text-align:left;margin-top:10px;padding:.85rem 1rem;border:2px solid var(--ink);border-radius:14px;color:#fff;font-weight:700;font-size:1rem;box-shadow:4px 4px 0 var(--ink);transition:.12s;background:var(--c)}.qo:hover{transform:translate(-2px,-2px);box-shadow:6px 6px 0 var(--ink)}.qo:active{transform:translate(2px,2px);box-shadow:0 0 0 var(--ink)}.qo .e{font-size:1.5rem}.qo.ok{background:#12B76A;animation:pp .4s}.qo.no{background:#ef4444;animation:shk .4s}.qo.dim{opacity:.4}.qo:disabled{cursor:default;transform:none}.tbar{height:8px;border-radius:9px;border:1.5px solid var(--cb);background:var(--c2);overflow:hidden}.tbar i{display:block;height:100%;background:var(--a);animation:tb 12s linear forwards}@keyframes tb{from{width:100%}to{width:0}}.hero-e{font-size:3rem;display:inline-block;animation:flt 3s ease-in-out infinite alternate}</style>');
function startQuiz(){S.qc={st:0,pl:[],qi:pickQs('quiz',QB.length,5),a:[null,null,null,null,null]};renderView()}
const qcPick=u=>{const c=S.qc,i=c.pl.indexOf(u);if(i>=0)c.pl.splice(i,1);else if(c.pl.length<2)c.pl.push(u);else toast('Pick up to 2 friends');renderView()};
const qcNext=()=>{const c=S.qc;if(c.st==0&&!c.pl.length)return toast('Pick at least 1 friend');c.st++;renderView()};
const qcBack=()=>{const c=S.qc;if(c.st<=0)S.qc=null;else c.st--;renderView()};
const qcAns=(i,j)=>{const c=S.qc;c.a[i]=j;buzz();renderView();setTimeout(()=>{if(S.qc===c&&c.st==i+1){c.st++;renderView()}},260)};
function quizMake(){const c=S.qc,f=friendIds(S.uid),hd=`<div style="display:flex;align-items:center;gap:10px"><button class="ghost" aria-label="Back" onclick="qcBack()">←</button><div class="bar" style="flex:1"><i style="width:${c.st/6*100}%"></i></div></div>`;
 if(c.st==0)return hd+`<div class="card" style="padding:18px;margin-top:12px;animation:none;text-align:center"><span class="hero-e">🤝</span><h2 style="font-weight:800;margin-top:6px">Who's playing?</h2><p style="color:var(--mu);margin-top:2px">Pick 1 or 2 friends. They will guess your answers.</p>${f.length?`<div class="scroll" style="flex-wrap:wrap;justify-content:center;margin-top:12px">${f.map(u=>`<button class="chip ${c.pl.includes(u)?'on':''}" onclick="qcPick('${u}')">${av(U(u).name,22)} ${esc(String(U(u).name).split(' ')[0])}</button>`).join('')}</div>`:'<p style="color:var(--mu);margin-top:10px">You need friends first. Add friends from Explore.</p>'}<button class="btn" style="width:100%;margin-top:16px" onclick="qcNext()">Next →</button></div>`;
 if(c.st<=5){const i=c.st-1,k=c.qi[i];return hd+`<div style="margin-top:14px;font-size:.75rem;font-weight:700;color:var(--mu)">ABOUT YOU · QUESTION ${c.st}/5</div><h2 style="font-weight:800;margin-top:4px">${esc(QB[k][0])}</h2>${QB[k][1].map((o,j)=>`<button class="qo" style="--c:${c.a[i]===j?'#1A1612':QCOL[j]}" onclick="qcAns(${i},${j})"><span class="e">${QE[k][j]}</span>${esc(o)}</button>`).join('')}`}
 return hd+`<div class="card" style="padding:18px;margin-top:12px;animation:none;text-align:center"><span class="hero-e">🎯</span><h2 style="font-weight:800;margin-top:6px">Ready to send?</h2><p style="color:var(--mu);margin-top:2px">${c.pl.map(u=>esc(String(U(u).name).split(' ')[0])).join(' and ')} will guess your 5 answers.</p><button class="btn" style="width:100%;margin-top:14px" onclick="sendQuiz()">Send challenge 🚀</button></div>`}
async function sendQuiz(){const c=S.qc;if(!c.pl.length)return toast('Pick at least 1 friend');if(c.a.some(x=>x===null))return toast('Answer all 5 questions');
 try{const r=await addDoc(collection(db,'quizzes'),{host:S.uid,hostName:U(S.uid).name||'Friend',players:[S.uid,...c.pl],qs:c.qi.map((k,i)=>({q:QB[k][0],opts:QB[k][1],em:QE[k],ans:c.a[i]})),guesses:{},ts:Date.now()});c.pl.forEach(u=>notify(u,'quiz',r.id));S.qc=null;renderView();confetti();toast('Challenge sent 🎮')}catch(e){toast(errMsg(e))}}
const playQuiz=id=>{S.qp={id,i:0,g:[],rv:null,t:0};renderView()};
const qpStop=()=>{if(S.qp&&S.qp.t)clearTimeout(S.qp.t)};
const qpBack=()=>{qpStop();S.qp=null;renderView()};
function qpAns(j){const p=S.qp;if(!p||p.rv)return;const q=quizzes.find(x=>x.id==p.id);if(!q)return;qpStop();const ans=q.qs[p.i].ans,ok=j===ans;p.g.push(j);p.rv={j,ans,ok};buzz();blip(ok);renderView();p.t=setTimeout(()=>qpNext(p.id),ok?800:1300)}
async function qpNext(id){const p=S.qp;if(!p||p.id!==id)return;const q=quizzes.find(x=>x.id==id);if(!q)return;
 if(p.i<4){p.i++;p.rv=null;return renderView()}
 try{await updateDoc(doc(db,'quizzes',id),{['guesses.'+S.uid]:p.g});notify(q.host,'quizdone',id);const g=p.g;S.qp=null;S.qr={id,gid:S.uid,g};renderView();if(qScore(q,g)>=4)confetti()}catch(e){toast(errMsg(e));p.g.pop();p.rv=null;renderView()}}
