const ideaV=()=>`<h2 style="font-size:1.4rem;font-weight:800">💡 Idea Lab</h2><p style="color:var(--mu);margin:4px 0 12px">Test your startup idea with AI, get honest votes from founders, find your team.</p>`+(S.idf?`<div class="card" style="padding:18px"><h3 style="font-weight:800">Test your idea 🧪</h3>${inp('Idea name','it','text','','e.g. AI tutor for school students')}<label class="l">What problem are you solving?</label><textarea id="ip" class="inp" rows="3" maxlength="500" placeholder="Who faces this problem and why does it hurt?"></textarea><label class="l">Who is your customer?</label><textarea id="ic" class="inp" rows="2" maxlength="300" placeholder="e.g. class 9-12 students in tier-2 cities"></textarea><label class="l">How will it earn money?</label><textarea id="im" class="inp" rows="2" maxlength="300" placeholder="e.g. ₹99/month subscription"></textarea>${inp('Teammate / skill you need (optional)','in','text','','e.g. developer, designer, marketer')}<div style="display:flex;gap:10px;margin-top:1.2rem"><button class="ghost" onclick="ideaForm()">Cancel</button><button id="ib" class="btn" style="flex:1" onclick="runIdea()">Test my idea 🚀</button></div></div>`:`<button class="btn" style="width:100%" onclick="ideaForm()">🧪 Test my idea with AI</button>`)+`<div id="ilist"></div>`;
function paintIdeas(){const el=$('ilist');if(!el)return;const a=document.activeElement;if(a&&el.contains(a)&&a.value)return;
 el.innerHTML=!ready?'<div class="sk"></div>':ideas.map(ideaC).join('')||`<div class="card" style="padding:40px;text-align:center;margin-top:14px;color:var(--mu)"><div style="font-size:2.2rem">🧪</div>No ideas tested yet.<br>Be the first to test yours!</div>`}
const IDM={P:['Problem saaf likhi hai aur asli dard dikhta hai','Problem abhi dhundhli hai. Kaun, kab aur kitna pareshan hota hai, ye likho','10 logon se puchho: ye problem kitni baar hoti hai aur abhi wo kya karte hain?'],C:['Customer specific hai, pehle 10 customers dhoondhna aasan hoga','Customer bahut bada ya vague hai. Pehle ek chhota group chuno','Ek hi customer group chuno aur unke 5 logon se milo ya call karo'],M:['Kamai ka tareeka samajh aata hai','Paisa kaise banega, ye saaf nahi hai. Price aur margin likho','Ek asli price tay karo aur 3 customers se puchho ki wo itna dene ko taiyaar hain ya nahi'],T:['Team ya skill ki zarurat pehchani hai, ye samajhdari hai','Team ya skill ka plan nahi hai. Akele sab karna mushkil hota hai','Neeche "I am interested" se jude logon ko chat karke team banao'],U:['Idea ka angle alag aur yaad rakhne layak hai','Doosron se alag kya hai, ye saaf nahi. Competitors dekho','Top 3 competitors ki list banao aur likho tumhara farak kya hai']};
function scoreIdea(d){const t=x=>(x||'').toLowerCase(),has=(x,w)=>w.some(k=>t(x).includes(k)),L=x=>(x||'').trim().length,cl=(v,m)=>Math.max(0,Math.min(m,v));
 const P=cl(L(d.problem)/12+(has(d.problem,['problem','dikkat','mushkil','pareshan','costly','mehenga','slow','delay','waste','nahi mil','fraud','difficult','hard','pain','time','paisa','milawat','adulter'])?6:0)+(/\d/.test(d.problem)?4:0),20);
 const C=cl(L(d.customer)/10+(/,| aur | and /.test(d.customer)?4:0)+(has(d.customer,['student','restaurant','cafe','tier','city','owner','class','household','business','b2b','b2c','shop','school','farmer','women','parents','freelanc','startup'])?6:0)-(has(d.customer,['everyone','sab log','sabhi','all people','koi bhi','har koi'])?8:0),20);
 const M=cl(L(d.money)/8+(has(d.money,['subscription','commission','price','margin','fee','ads','contract','per ','monthly','premium','sell','charge','₹','rs','license'])?10:0)+(/[\d₹%]/.test(d.money)?7:0)-(has(d.money,['baad me','later','pata nahi','not sure','dekhenge'])?8:0),25);
 const T=cl((L(d.need)>3?8:0)+(has(d.need,['develop','design','market','sales','operation','video','finance','content','editor','manager','engineer'])?7:0),15);
 const U=cl((L(d.title)>=8&&L(d.title)<=60?5:2)+(has(d.title+' '+d.problem,['unique','only','first','local','fresh','ai','platform','direct','farm','niche','subscription','delivery','marketplace','app','network'])?10:3)+(L(d.problem)>60?5:2),20);
 const sc=Math.max(5,Math.min(85,Math.round((P+C+M+T+U)*.85))),dm=[['P',P,20],['C',C,20],['M',M,25],['T',T,15],['U',U,20]].map(([k,v,m])=>({k,r:v/m})),pros=[],cons=[];
 dm.forEach(x=>{if(x.r>=.7)pros.push(IDM[x.k][0]);else if(x.r<.5)cons.push(IDM[x.k][1])});
 pros.length=Math.min(pros.length,4);cons.unshift('Ye score sirf dekhta hai ki idea kitna saaf likha hai, market ki sachchai nahi. Asli customers se test karna zaroori hai');while(pros.length<2)pros.push(['Idea likh kar socha, ye pehla aur zaroori kadam hai','Is idea me sach me hal nikalne ki koshish dikhti hai'][pros.length]);
 while(cons.length<3)cons.push(['Competition aur cost ka hisaab abhi baaki hai','Abhi sab andaaza hai, 10 asli logon se baat karke pakka karo'][cons.length-1]);
 const steps=[...dm].sort((a,b)=>a.r-b.r).slice(0,3).map(x=>IDM[x.k][2]),team=(d.need||'').split(/,| aur | and /).map(x=>x.trim()).filter(x=>x.length>2).slice(0,3).map(x=>x.slice(0,80));
 if(team.length<2)team.push('Customer se baat karne wala (sales / outreach)');if(team.length<2)team.push('Jo pehla version bana sake (builder)');
 const sm=sc>=68?'Mazboot shuruaat! Problem, customer aur kamai saaf likhe hain. Ab asli customers par test karo.':sc>=50?'Achha idea hai, par kuch hisse abhi kamzor hain. Neeche ke negative points pehle theek karo.':sc>=30?'Idea me dam hai, par details kam hain. Problem, customer aur kamai ko aur saaf likho.':'Abhi idea kachcha hai. Pehle problem aur customer saaf karo, phir dobara test karo.';
 return{score:sc,summary:sm,pros,cons,steps,team}}
async function runIdea(){if(S.ibusy)return;const g=i=>($(i).value||'').trim(),d={title:g('it').slice(0,80),problem:g('ip').slice(0,500),customer:g('ic').slice(0,300),money:g('im').slice(0,300),need:g('in').slice(0,200)};
 if(d.title.length<3||d.problem.length<10)return toast('Add idea name and problem (min 10 characters)');
 S.ibusy=true;$('ib').disabled=true;
 try{await addDoc(collection(db,'ideas'),{uid:S.uid,...d,ai:scoreIdea(d),votes:{},joins:{},ts:Date.now()});S.idf=false;toast('Idea scored ✨')}catch(e){toast(errMsg(e))}
 S.ibusy=false;if(!S.idf)renderView();else if($('ib'))$('ib').disabled=false}
