// ---------- privacy: move email/phone/dob to a private document ----------
async function migPriv(){const m=users[S.uid];if(!m||S.mig==S.uid||!('phone' in m||'dob' in m||'email' in m))return;S.mig=S.uid;
 try{await setDoc(doc(db,'users',S.uid,'private','info'),{email:m.email||auth.currentUser?.email||'',phone:m.phone||'',dob:m.dob||''},{merge:true});await updateDoc(doc(db,'users',S.uid),{email:deleteField(),phone:deleteField(),dob:deleteField()})}catch(e){S.mig=0;console.warn('privacy migration',e)}}

// ---------- FoundX Team: official daily question (admin only) ----------
const PROMPTS=['Aapka pehla customer ya pehla user kaun tha? Kaise mila?','Is hafte aap kya bana rahe ho? Ek line mein batao.','Ek galti jisse aapne sabse zyada seekha?','Abhi aapko kis skill ki sabse zyada zarurat hai?','Apna idea ek line mein likho: kaun, kya problem, kaise solve?','Aaj ka win: aaj kya chhota sa accha hua?','Agar aapko ₹10,000 mil jaye, to business mein kahan lagaoge?','Aap kis skill mein doosron ki madad kar sakte ho?','Kaunsi app ya service India ko chahiye, jo abhi nahi hai?','Kaunsi ek aadat aapko roz aage badhati hai?','Startup shuru karne mein aapka sabse bada darr kya hai?','Koi book, video ya resource jisne aapki madad ki?'];
function teamCard(){const t=PROMPTS[(S.pi||0)%PROMPTS.length];return `<div class="card" style="padding:16px;margin-top:14px"><h3 style="font-weight:800">🧡 FoundX Team: daily question</h3><p style="margin-top:6px">${esc(t)}</p><div style="display:flex;gap:8px;margin-top:10px"><button class="ghost" onclick="S.pi=(S.pi||0)+1;renderView()">🔀 Another</button><button class="btn" style="flex:1" onclick="teamPost()">📣 Post as FoundX Team</button></div><p style="font-size:.78rem;color:var(--mu);margin-top:8px">Shows as an Official post. Real members answer in the comments.</p></div>`}
async function teamPost(){const t=PROMPTS[(S.pi||0)%PROMPTS.length];try{await addDoc(collection(db,'posts'),{uid:S.uid,t:'🧡 Daily question: '+t,img:'',likes:[],cm:[],ts:Date.now(),official:true});S.pi=(S.pi||0)+1;toast('Posted as FoundX Team 🚀');renderView()}catch(e){toast(errMsg(e))}}

// ---------- growth & safety: referrals, alerts, report/block ----------
try{const r=new URLSearchParams(location.search).get('ref');if(r&&/^[A-Za-z0-9]{10,40}$/.test(r))localStorage.setItem('fx_ref',r)}catch(e){}
const REFURL=()=>location.origin+location.pathname+'?ref='+S.uid;
const copyRef=()=>{navigator.clipboard?.writeText(REFURL());toast('Invite link copied 🎁')};
const shareRef=()=>window.open('https://wa.me/?text='+encodeURIComponent('Join my squad on FoundX: weekly challenges, streaks and badges with friends. '+REFURL()),'_blank');
const REFGOAL=5;
const refBox=()=>{const pend=myo.some(o=>o.txn=='REFERRAL'&&o.status=='pending'),has=perks[S.uid]?.tag;
 const reward=has?`<div style="margin-top:10px;font-size:.88rem">✅ You already have a tag${perks[S.uid].free?' from inviting friends':''}.</div>`:pend?`<div style="margin-top:10px;font-size:.88rem">⏳ Reward claim sent. It goes live after approval.</div>`:refN>=REFGOAL?`<div style="margin-top:10px"><b>🎉 You unlocked a free tag + blue tick!</b><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px"><select id="rt" class="inp" style="flex:1;min-width:140px">${TAGS.map(x=>`<option>${x}</option>`).join('')}</select><button class="btn" onclick="claimRef()">Claim reward</button></div></div>`:`<div style="margin-top:10px;font-size:.85rem;color:var(--mu)">Invite ${REFGOAL-refN} more friend${REFGOAL-refN>1?'s':''} to unlock a <b style="color:var(--tx)">free tag + blue tick</b>.</div><div class="bar" style="margin-top:6px"><i style="width:${Math.min(100,refN/REFGOAL*100)}%"></i></div>`;
 return `<div class="card" style="padding:14px;margin-top:12px"><b>🎁 Invite friends, earn 100 points each</b><div style="color:var(--mu);font-size:.85rem;margin-top:2px">${refN} joined · <b style="color:var(--tx)">${refN*100} points</b> · 500 points = free tag + blue tick</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="btn" onclick="shareRef()">Share on WhatsApp</button><button class="ghost" onclick="copyRef()">Copy link</button></div>${reward}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;border-top:1.5px solid var(--bd);padding-top:12px"><button class="ghost" onclick="shareProfile('${S.uid}')">🔗 Share my profile</button>${installBtn()}</div></div>`};
async function claimRef(){const t=$('rt')?.value||TAGS[0];if(refN<REFGOAL)return toast('Invite '+REFGOAL+' friends first');try{await addDoc(collection(db,'orders'),{uid:S.uid,kind:'tag',tag:t,name:U(S.uid).name||'',email:auth.currentUser?.email||'',txn:'REFERRAL',amt:0,status:'pending',ts:Date.now()});toast('Claim sent ✅ We will approve it soon')}catch(e){toast(errMsg(e))}}
const NT={};
function notify(to,type,pid){if(!to||to==S.uid)return;const k=to+type+(pid||''),n=Date.now();if(NT[k]&&n-NT[k]<3e5)return;NT[k]=n;addDoc(collection(db,'notifs'),{to,from:S.uid,type,pid:pid||'',ts:n,read:false}).catch(()=>{})}
const NTX={sync:'invited you to Match Up',syncdone:'finished Match Up. See your result!',quiz:'challenged you: how well do you know them?',quizdone:'finished your quiz',squad:'added you to a squad',freq:'sent you a friend request',facc:'accepted your friend request',like:'found your post helpful',comment:'commented on your post',message:'sent you a message'};
function notifV(){const un=notifs.filter(x=>!x.read).length;setTimeout(()=>{if(S.view=='notif')readAll()},2500);return `<div style="display:flex;align-items:center;gap:10px"><h2 style="font-size:1.4rem;font-weight:800;flex:1">🔔 Alerts${un?` <span class="badge" style="--c:#FF5A1F">${un} new</span>`:''}</h2>${un?'<button class="ghost" onclick="readAll()">Mark all read</button>':''}</div>`+notifCard()+reqCard()+(notifs.length?notifs.slice(0,50).map(n=>`<div class="card" style="padding:12px 14px;margin-top:10px;display:flex;gap:10px;align-items:center;cursor:pointer;${n.read?'':'border-color:var(--a)'}" onclick="openN('${n.id}')">${av(U(n.from).name,34,n.from)}<div style="flex:1"><b>${esc(U(n.from).name)}</b> ${NTX[n.type]||'did something'}<div style="font-size:.75rem;color:var(--mu)">${ago(n.ts)}</div></div>${n.read?'':'<span style="width:10px;height:10px;border-radius:50%;background:var(--a)"></span>'}</div>`).join(''):`<div class="card" style="padding:40px;text-align:center;margin-top:14px;color:var(--mu)"><div style="font-size:2.2rem">🔔</div>No alerts yet.<br>Likes, comments and messages will show up here.</div>`)}
async function openN(id){const n=notifs.find(x=>x.id==id);if(!n)return;try{await updateDoc(doc(db,'notifs',id),{read:true})}catch(e){}if(n.type=='message')dm(n.from);else if(n.type=='freq'||n.type=='facc')go('profile',{peer:n.from});else if(n.type=='squad')go('squad');else if(n.type=='quiz'||n.type=='quizdone'||n.type=='sync'||n.type=='syncdone')go('quiz');else go('feed')}
const readAll=()=>notifs.filter(x=>!x.read).forEach(n=>updateDoc(doc(db,'notifs',n.id),{read:true}).catch(()=>{}));
async function report(kind,target){const r=(prompt('Why are you reporting this? (spam, abuse, fake, other)')||'').trim().slice(0,200);if(!r)return;try{await addDoc(collection(db,'reports'),{by:S.uid,kind,target,reason:r,ts:Date.now()});toast('Thanks, we will review it.')}catch(e){toast(errMsg(e))}}
async function toggleBlock(id){const b=(U(S.uid).blocks||[]).includes(id);if(!b&&!confirm('Block this person? You will no longer see their posts.'))return;try{await updateDoc(doc(db,'users',S.uid),{blocks:b?arrayRemove(id):arrayUnion(id)});toast(b?'Unblocked':'Blocked');renderView()}catch(e){toast(errMsg(e))}}
const peerAct=id=>`<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;align-items:center"><button class="ghost" aria-label="More" title="More" onclick="S.pm=!S.pm;renderView()">${icn('dots',20)}</button>${S.pm?`<button class="ghost" onclick="shareProfile('${id}')">🔗 Share</button><button class="ghost" onclick="report('user','${id}')">🚩 Report</button><button class="ghost" onclick="toggleBlock('${id}')">${(U(S.uid).blocks||[]).includes(id)?'Unblock':'🚫 Block'}</button>`:''}</div>`;
const resolveRep=id=>deleteDoc(doc(db,'reports',id)).then(()=>toast('Marked resolved')).catch(e=>toast(errMsg(e)));
const repCard=()=>`<div class="card" style="padding:16px;margin-top:14px"><h3 style="font-weight:800">🚩 Reports (admin)</h3>${reps.map(r=>`<div style="margin-top:10px;border-top:1.5px solid var(--bd);padding-top:8px"><b>${esc(r.kind)}</b> · ${esc(r.reason)}<div style="font-size:.78rem;color:var(--mu);word-break:break-all">target: ${esc(r.target)} · by ${esc(U(r.by).name)}</div><button class="ghost" style="margin-top:6px" onclick="resolveRep('${r.id}')">Mark resolved</button></div>`).join('')||'<p style="color:var(--mu);margin-top:8px">No reports.</p>'}</div>`;

