let IP=null,DEEP=null;
try{const q=new URLSearchParams(location.search).get('u');if(q&&/^[A-Za-z0-9]{10,40}$/.test(q))DEEP=q}catch(e){}
addEventListener('beforeinstallprompt',e=>{e.preventDefault();IP=e;if(S.view=='profile'&&!S.edit)renderView()});
