const installBtn=()=>IP?'<button class="btn" onclick="installApp()">📲 Install app</button>':isIOS()?'<span style="font-size:.8rem;color:var(--mu);align-self:center">📲 To install: tap Share, then Add to Home Screen</span>':'';
async function installApp(){if(!IP)return;IP.prompt();try{await IP.userChoice}catch(e){}IP=null;renderView()}
