async function shareProfile(id){const url=location.origin+location.pathname+'?u='+id,t=(U(id).name||'A founder')+' on FoundX';
 try{if(navigator.share){await navigator.share({title:t,text:'Check out '+t,url});return}}catch(e){if(e&&e.name=='AbortError')return}
 try{await navigator.clipboard.writeText(url);toast('Profile link copied 🔗')}catch(e){prompt('Copy this link',url)}}
let STX='';
const statsCard=()=>{const D=864e5,now=Date.now(),us=Object.values(users),cr=u=>u.created||0,nu=d=>us.filter(u=>now-cr(u)<d*D).length,act=d=>us.filter(u=>now-(u.lastSeen||0)<d*D).length;
 const pw=posts.filter(p=>!p.official&&now-p.ts<7*D),pp=new Set(pw.map(p=>p.uid)).size,cm=posts.reduce((a,p)=>a+(p.cm||[]).length,0),rf=Object.values(refAll).reduce((a,b)=>a+b,0);
 const paid=orders.filter(o=>o.status=='done'&&o.amt>0),rev=paid.reduce((a,o)=>a+o.amt,0),t0=new Date().setHours(0,0,0,0);
 const days=Array.from({length:14},(_,i)=>{const a=t0-(13-i)*D;return us.filter(u=>cr(u)>=a&&cr(u)<a+D).length}),mx=Math.max(1,...days);
 STX=`FoundX traction (${new Date().toLocaleDateString('en-IN')}): ${us.length} members · ${nu(7)} new in 7 days · ${act(7)} active in 7 days · ${pw.length} posts in 7 days by ${pp} members · ${rf} referral signups · ${paid.length} paid orders (₹${rev})`;
 const tile=(l,v)=>`<div style="background:var(--c2);border-radius:12px;padding:10px 12px"><div style="font-size:.7rem;color:var(--mu);font-weight:700">${l}</div><div style="font-size:1.3rem;font-weight:800">${v}</div></div>`;
 return `<div class="card" style="padding:16px;margin-top:14px"><h3 style="font-weight:800">📈 Traction (real data, admin only)</h3><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:10px">${tile('MEMBERS',us.length)}${tile('NEW (7 DAYS)',nu(7))}${tile('NEW TODAY',nu(1))}${tile('ACTIVE (24H)',act(1))}${tile('ACTIVE (7 DAYS)',act(7))}${tile('POSTS (7 DAYS)',pw.length+' · '+pp+' people')}${tile('COMMENTS (RECENT)',cm)}${tile('REFERRAL SIGNUPS',rf)}${tile('CAME BACK (2+ DAYS)',us.filter(u=>(u.dayCount||0)>=2).length)}${tile('AVG DAYS VISITED',(us.reduce((a,u)=>a+(u.dayCount||0),0)/Math.max(1,us.length)).toFixed(1))}${tile('PAID ORDERS',paid.length+' · ₹'+rev)}</div>
<div style="font-size:.7rem;color:var(--mu);font-weight:700;margin-top:12px">NEW MEMBERS, LAST 14 DAYS</div><div style="display:flex;align-items:flex-end;gap:3px;height:56px;margin-top:6px">${days.map(v=>`<div title="${v}" style="flex:1;background:var(--a);border-radius:3px 3px 0 0;height:${Math.max(3,v/mx*100)}%;opacity:${v?1:.25}"></div>`).join('')}</div>
<button class="ghost" style="margin-top:12px" onclick="copyStats()">📋 Copy summary for pitch deck</button><p style="font-size:.72rem;color:var(--mu);margin-top:8px">Based on loaded data: latest 150 posts and 30 orders.</p></div>`};
const copyStats=()=>{navigator.clipboard?.writeText(STX).then(()=>toast('Summary copied')).catch(()=>prompt('Copy this',STX))};

