function go(v,x={}){stopFind();Object.assign(S,{view:v,edit:false,peer:null,group:null,chat:false,pm:false,sq:null,qc:null,qp:null,qr:null,sx:null,sa:null,sc:null,pl:false},x);if(v=='msgs'&&!S.room&&!S.peer&&!S.group)S.room='Tech';if(v=='msgs')watchChat();render();scrollTo(0,0)}
function render(){theme();const a=$('app');
 if(!S.uid){S.mode=S.mode=='onboard'?'login':S.mode;a.innerHTML=authV();return}
 if(!ready||S.busy){a.innerHTML='<div style="display:grid;place-items:center;height:100vh"><div class="logo" style="font-size:2rem">found</div></div>';return}
 if(!me()){if(S.mode!='onboard'){S.mode='onboard';S.step=1;D.name=auth.currentUser?.displayName||'';D.age=''}a.innerHTML=authV();return}
 const m=me();
 a.innerHTML=`<header class="mtop"><span class="logo">found</span><span style="flex:1"></span>${bellBtn('bm')}<button title="More" aria-label="More" onclick="openMore()">${icn('dots',22)}</button></header><div class="shell"><aside class="side"><div style="display:flex;align-items:center;padding:6px 12px"><span class="logo">found</span><span style="flex:1"></span>${bellBtn('bd')}</div><button class="btn" style="width:100%;margin-bottom:12px;display:flex;align-items:center;justify-content:center;gap:6px" onclick="composePost()">${icn('plus',18)} New post</button><div class="card" style="padding:8px">${NAV.map(([v,i,l])=>`<button class="nav ${S.view==v?'on':''}" onclick="go('${v}')"><span>${i}</span>${l}</button>`).join('')}${moreSide()}<button class="nav" onclick="localStorage.fxTheme=localStorage.fxTheme=='dark'?'light':'dark';render()"><span>${icn('moon',20)}</span>Theme</button></div>
 <div class="card" style="padding:12px"><div style="display:flex;gap:10px;align-items:center">${av(m.name,36,S.uid)}<div style="flex:1;min-width:0"><b style="font-size:.88rem">${esc(m.name)}</b><div style="font-size:.72rem;color:var(--mu)">🔥 ${streak(S.uid)} day streak</div></div><button title="Logout" onclick="signOutNow()">⎋</button></div><select class="inp" style="margin-top:10px;padding:.4rem .6rem;font-size:.82rem" onchange="setAvail(this.value)">${AVL.map(x=>`<option ${x==(m.avail||'Available')?'selected':''}>${x}</option>`).join('')}</select></div></aside>
 <main id="view"></main><aside class="rp" id="rp"></aside></div>
 <nav class="tabbar">${tabs()}</nav>`;
 renderView();paintRight()}
Object.assign(window,{postSheet,openMore,toggleTheme,composePost,enableNotif,toggleSnd,hideGs,copyStats,shareProfile,installApp,claimRef,openN,readAll,report,toggleBlock,copyRef,shareRef,resolveRep,teamPost,tgl,gPick,gAns,gNext,pickShop,submitOrder,okOrder,noOrder,joinIdea,ideaForm,runIdea,voteIdea,delIdea,S,D,render,renderView,go,grab,setD,next,doLogin,post,pick,prev,like,cmt,tg,share,del,room,dm,openGroup,send,cpick,saveEdit,paintExplore,paintList,newGroup,makeGroup,groupInfo,addMembers,leaveGroup,newStory,spick,shareStory,openStory,stNav,delStory,closeOv,setAvail,signOutNow:()=>signOut(auth)});

// ---------- guest mode: view only, no account ----------
async function guestIn(){try{await signInAnonymously(auth)}catch(e){toast(e.code=='auth/operation-not-allowed'?'Guest login abhi on nahi hai':errMsg(e))}}
function needAcc(){toast('Ye karne ke liye account banao 🙂');if(S.guest){S.mode='signup';S.step=1;signOut(auth)}}
const guestBar=()=>S.guest?`<div class="card" style="padding:12px 14px;margin-bottom:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap"><span style="flex:1;min-width:180px;font-size:.88rem">👀 Aap guest ho: dekh sakte ho, par chat, like, comment, post nahi kar sakte.</span><button class="btn" onclick="needAcc()">Account banao</button></div>`:'';
['post','postSheet','composePost','like','cmt','send','cpick','dm','room','openGroup','newGroup','makeGroup','addMembers','newStory','shareStory','voteIdea','joinIdea','runIdea','delIdea','del','report','toggleBlock','saveEdit','setAvail','claimRef','submitOrder','teamPost'].forEach(n=>{const f=window[n];if(typeof f=='function')window[n]=(...a)=>S.guest?needAcc():f(...a)});
const go0=window.go;window.go=(v,x={})=>S.guest&&(['msgs','shop','notif','refer'].includes(v)||(v=='profile'&&!x.peer))?needAcc():go0(v,x);
Object.assign(window,{needAcc,guestIn});

// ---------- forgot password + email verification ----------
async function resetPw(){grab();if(!/^\S+@\S+\.\S+$/.test(D.email||''))return toast('Pehle upar apna email likho');try{await sendPasswordResetEmail(auth,D.email);toast('Reset link bhej diya ✅ Inbox ya spam dekho')}catch(e){toast(errMsg(e))}}
const verBar=()=>{const u=auth.currentUser;if(S.guest||!u||u.emailVerified||S.vh)return '';return `<div class="card" style="padding:12px 14px;margin-bottom:12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap"><span style="flex:1;min-width:180px;font-size:.88rem">📧 Apna email verify karo, taaki account safe rahe aur password reset ho sake.</span><button class="btn" onclick="sendVer()">Link bhejo</button><button class="ghost" onclick="chkVer()">Maine verify kar liya</button><button class="ghost" aria-label="Close" onclick="S.vh=1;renderView()">✕</button></div>`};
async function sendVer(){try{await sendEmailVerification(auth.currentUser);toast('Verification link bhej diya ✅ Inbox ya spam dekho')}catch(e){toast(errMsg(e))}}
async function chkVer(){try{await auth.currentUser.reload();toast(auth.currentUser.emailVerified?'Email verify ho gaya ✅':'Abhi verify nahi hua. Mail ka link khol kar aao');renderView()}catch(e){toast(errMsg(e))}}
Object.assign(window,{resetPw,sendVer,chkVer});

// ---------- passwordless login: one-time email link ----------
async function sendLink(){grab();if(!/^\S+@\S+\.\S+$/.test(D.email||''))return toast('Pehle upar apna email likho');
 try{await sendSignInLinkToEmail(auth,D.email,{url:location.origin+location.pathname,handleCodeInApp:true});try{localStorage.setItem('fx_le',D.email)}catch(e){}toast('Login link bhej diya ✅ Inbox ya spam dekho')}
 catch(e){toast(e.code=='auth/operation-not-allowed'?'Email link login Firebase mein abhi on nahi hai':errMsg(e))}}
(async()=>{try{if(!isSignInWithEmailLink(auth,location.href))return;let em='';try{em=localStorage.getItem('fx_le')||''}catch(e){}
 if(!em)em=(prompt('Confirm karne ke liye apna email likho')||'').trim();if(!em)return;
 await signInWithEmailLink(auth,em,location.href);try{localStorage.removeItem('fx_le')}catch(e){}
 try{history.replaceState(null,'',location.pathname)}catch(e){}toast('Login ho gaya ✅')}
 catch(e){try{history.replaceState(null,'',location.pathname)}catch(x){}toast(errMsg(e))}})();
Object.assign(window,{sendLink});
render();
